import{_ as n,o as a,c as p,a2 as t}from"./chunks/framework.C4u7U0Dw.js";const d=JSON.parse('{"title":"电商与直播提示词模板","description":"电商与直播带货的 5 条提示词模板：详情页文案、标题关键词、差评回复、直播讲品脚本、竞品对比。","frontmatter":{"title":"电商与直播提示词模板","description":"电商与直播带货的 5 条提示词模板：详情页文案、标题关键词、差评回复、直播讲品脚本、竞品对比。"},"headers":[],"relativePath":"community/prompts/电商与直播.md","filePath":"community/prompts/电商与直播.md"}'),e={name:"community/prompts/电商与直播.md"};function l(o,s,i,c,r,u){return a(),p("div",null,[...s[0]||(s[0]=[t(`<h1 id="🛒-电商与直播带货-·-5-条提示词模板" tabindex="-1">🛒 电商与直播带货 · 5 条提示词模板 <a class="header-anchor" href="#🛒-电商与直播带货-·-5-条提示词模板" aria-label="Permalink to &quot;🛒 电商与直播带货 · 5 条提示词模板&quot;">​</a></h1><blockquote><p>这行的痛苦很集中：<strong>东西一样，就是说不出来</strong>。 参数你都知道，就是不知道怎么变成人话、变成点击、变成下单。</p></blockquote><h2 id="本行三句话骨架" tabindex="-1">本行三句话骨架 <a class="header-anchor" href="#本行三句话骨架" aria-label="Permalink to &quot;本行三句话骨架&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我卖的是【什么品类 / 价格带 / 卖给谁】。</span></span>
<span class="line"><span>帮我产出【文案 / 标题 / 话术】，数量【…】，长度【…】。</span></span>
<span class="line"><span>风格按【哪个平台 / 你给的样例】来；参数只能用我给的真实数据，不许编功效。</span></span></code></pre></div><hr><h2 id="_1-·-商品参数-→-详情页文案" tabindex="-1">1 · 商品参数 → 详情页文案 <a class="header-anchor" href="#_1-·-商品参数-→-详情页文案" aria-label="Permalink to &quot;1 · 商品参数 → 详情页文案&quot;">​</a></h2><p><strong>什么时候用</strong>：厂家给了你一堆参数（材质、尺寸、功率、成分），你要变成买家看得懂、想买的那几段。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我的商品：【商品名】</span></span>
<span class="line"><span>真实参数：【把厂家给的参数原样粘贴，不要美化】</span></span>
<span class="line"><span>买家是谁：【年龄 / 性别 / 什么场景下买 / 最在意什么】</span></span>
<span class="line"><span>价格：【…】元，和同类比是【偏贵 / 差不多 / 便宜】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>帮我写详情页文案，结构：</span></span>
<span class="line"><span>① 一句话卖点（15 字内，能当主图上的大字）</span></span>
<span class="line"><span>② 三个&quot;场景化&quot;小标题（不要写参数名，写买家的实际处境）</span></span>
<span class="line"><span>③ 每个小标题下 2 句解释，把参数翻译成&quot;对买家意味着什么&quot;</span></span>
<span class="line"><span>④ 一段&quot;适合谁 / 不适合谁&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>规矩：</span></span>
<span class="line"><span>- 参数只能用我给的，不许自己加（不许出现&quot;抗菌&quot;&quot;食品级&quot;这类我没说的词）</span></span>
<span class="line"><span>- 不许写&quot;国家级&quot;&quot;最&quot;这种绝对化词，平台会罚</span></span>
<span class="line"><span>- 不许编用户评价</span></span></code></pre></div><p><strong>它给你</strong>：可直接排版的详情页文案。<strong>第④段&quot;不适合谁&quot;别删</strong>——这是退货率最低的一段文案。</p><hr><h2 id="_2-·-标题与关键词-一稿多平台" tabindex="-1">2 · 标题与关键词（一稿多平台） <a class="header-anchor" href="#_2-·-标题与关键词-一稿多平台" aria-label="Permalink to &quot;2 · 标题与关键词（一稿多平台）&quot;">​</a></h2><p><strong>什么时候用</strong>：同一个商品，淘宝、抖音、拼多多、小红书的标题逻辑完全不同，一个个想很费时间。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>商品：【商品名 + 核心参数 + 价格带】</span></span>
<span class="line"><span>目标平台：淘宝 / 抖音 / 拼多多 / 小红书（我逐个要）</span></span>
<span class="line"><span>买家搜索时最可能输入的词（我自己想到的）：【罗列关键词，没有就写&quot;不确定&quot;】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>每个平台给我 5 个标题，并说明：</span></span>
<span class="line"><span>① 这个平台的标题在&quot;抢什么&quot;（搜索词？点击？情绪？）</span></span>
<span class="line"><span>② 每个标题的字数、包含的核心词</span></span>
<span class="line"><span>③ 哪些词是可以组合复用的&quot;词根&quot;</span></span>
<span class="line"><span>最后单独给我一张&quot;词根表&quot;，我以后自己拼。</span></span></code></pre></div><p><strong>它给你</strong>：4 个平台 × 5 个标题 + 一张词根表。<strong>词根表是长期资产</strong>——以后新品直接用。</p><hr><h2 id="_3-·-差评与售后回复-分场景给话术" tabindex="-1">3 · 差评与售后回复（分场景给话术） <a class="header-anchor" href="#_3-·-差评与售后回复-分场景给话术" aria-label="Permalink to &quot;3 · 差评与售后回复（分场景给话术）&quot;">​</a></h2><p><strong>什么时候用</strong>：差评来了，气头上乱回一句，事情只会更大。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这是买家的原话（差评 / 投诉 / 售后要求）：</span></span>
<span class="line"><span>【粘贴原话】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>订单背景：【什么商品 / 买了多久 / 之前有没有沟通过 / 我们这边确实有没有问题】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请按三种情况分别给我回复话术：</span></span>
<span class="line"><span>① 确实是我们错了（先认，再给具体补救方案，给两个选项）</span></span>
<span class="line"><span>② 是误会 / 使用问题（不指责买家，用&quot;可能是……&quot;的句式，附一句怎么用才对）</span></span>
<span class="line"><span>③ 对方要价超出规则（如何不激怒地说明规则，并给一个折中方案）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>额外给我：一句&quot;公开发布&quot;的简短回应（其他买家也会看到，不要太长）。</span></span>
<span class="line"><span>规矩：不承诺我做不到的事；所有补偿方案必须是我能自己控制的（退款、补发、优惠券）。</span></span></code></pre></div><p><strong>它给你</strong>：三套话术 + 一句公开回应。<strong>&quot;不承诺我做不到的事&quot;这句必须留</strong>——AI 很爱替你答应&quot;无理由全额退&quot;。</p><hr><h2 id="_4-·-直播讲品脚本-3-分钟一个循环" tabindex="-1">4 · 直播讲品脚本（3 分钟一个循环） <a class="header-anchor" href="#_4-·-直播讲品脚本-3-分钟一个循环" aria-label="Permalink to &quot;4 · 直播讲品脚本（3 分钟一个循环）&quot;">​</a></h2><p><strong>什么时候用</strong>：直播时同一个品要讲几十遍，讲到最后自己都烦了，话也越来越干。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我要在直播间讲这个品：【商品 + 真实参数 + 到手价 + 库存】</span></span>
<span class="line"><span>观众是谁：【…】，他们停留在我直播间大概【…】秒</span></span>
<span class="line"><span>我的直播风格：【热情直给 / 慢条斯理讲知识 / 幽默】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>帮我写一个 3 分钟的讲品循环脚本：</span></span>
<span class="line"><span>① 0-15 秒：钩子（为什么现在别划走）</span></span>
<span class="line"><span>② 15-60 秒：痛点 + 场景（不要讲参数，讲生活）</span></span>
<span class="line"><span>③ 60-120 秒：产品怎么解决 + 一个真实可验证的细节</span></span>
<span class="line"><span>④ 120-180 秒：价格锚点 + 库存紧迫 + 明确的动作指令</span></span>
<span class="line"><span></span></span>
<span class="line"><span>再给我：3 句可以反复说的&quot;口头禅式&quot;短句，方便我循环。</span></span>
<span class="line"><span>规矩：不许编销量、不许编&quot;最后 5 单&quot;这种我不掌握的库存数字；不确定的地方标出来由我自己填。</span></span></code></pre></div><p><strong>它给你</strong>：一个可循环的脚本骨架 + 3 句口头禅。<strong>脚本是骨架，不是让你念稿</strong>——念稿会被听出来。</p><hr><h2 id="_5-·-竞品对比表-定价参考" tabindex="-1">5 · 竞品对比表 + 定价参考 <a class="header-anchor" href="#_5-·-竞品对比表-定价参考" aria-label="Permalink to &quot;5 · 竞品对比表 + 定价参考&quot;">​</a></h2><p><strong>什么时候用</strong>：上新前，你想知道自己这个价格站不站得住。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我的商品：【名称 + 核心参数 + 我的成本区间 + 我打算卖多少】</span></span>
<span class="line"><span>我要对比的竞品（我只给你我自己查到的公开信息）：</span></span>
<span class="line"><span>①【竞品名 / 价格 / 已知参数 / 我看到的卖点】</span></span>
<span class="line"><span>②【…】</span></span>
<span class="line"><span>③【…】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>帮我：</span></span>
<span class="line"><span>① 做一张对比表（维度我自己定，你建议维度也行）</span></span>
<span class="line"><span>② 指出我在哪一维是明显劣势，然后给我三个&quot;绕开这个劣势&quot;的说法方向（不是骗人，是换对比维度）</span></span>
<span class="line"><span>③ 列出我还没掌握、但定价前必须搞清楚的信息清单</span></span>
<span class="line"><span>规矩：不确定的竞品参数一律标&quot;未知&quot;，绝对不许替我&quot;大概估一个&quot;。</span></span></code></pre></div><p><strong>它给你</strong>：对比表 + 差异化话术方向 + 待查清单。<strong>&quot;不许估&quot;是硬要求</strong>——编出来的竞品参数会让你定错价。</p><hr><h2 id="⚠️-这行的三条红线" tabindex="-1">⚠️ 这行的三条红线 <a class="header-anchor" href="#⚠️-这行的三条红线" aria-label="Permalink to &quot;⚠️ 这行的三条红线&quot;">​</a></h2><ol><li><strong>绝对化用语别用</strong>：最、第一、国家级、独家、顶级——各平台都在罚这个。让 AI 检查一遍你的文案里有没有。</li><li><strong>功效不能编</strong>：尤其是食品、化妆品、母婴、保健相关。AI 很喜欢加一句&quot;改善睡眠&quot;&quot;纯天然&quot;，<strong>它加了你就要删</strong>。</li><li><strong>用户评价、销量数字不能编</strong>：宁可写&quot;暂无评价&quot;。假的迟早被截图。</li></ol><hr><p><strong>目录</strong>：<a href="/MoMAWork-/community/prompts/">← 回到行业提示词模板库</a> ｜ 下一个行业 → <strong><a href="/MoMAWork-/community/prompts/实体门店与餐饮.html">实体门店与餐饮</a></strong></p>`,34)])])}const g=n(e,[["render",l]]);export{d as __pageData,g as default};
